/* Contenido de «IA para Turismo y Hotelería». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-ia-turismo",{"l":{"c-ia-turismo-m1-l1":[{"tipo":"texto","texto":"La mayoría de las cotizaciones se pierden por dos razones: llegaron tarde o estaban incompletas («¿los traslados están incluidos?», «¿es por persona o por habitación?»). La IA te arma la cotización en minutos con un formato fijo; los precios, la disponibilidad y las comisiones salen de tus proveedores, no de la IA."},{"tipo":"plantilla","rotulo":"Cotización completa","texto":"Arma una cotización para [número] personas a [destino], del [fecha] al [fecha], con estos servicios y precios que ya confirmé: [hospedaje, categoría y régimen; traslados; tours; seguro]. Formato: 1) resumen en 3 renglones, 2) tabla de qué incluye y qué NO incluye, 3) precio total y precio por persona, 4) anticipo y fecha límite de pago, 5) política de cancelación. Tono cordial, máximo una cuartilla. No agregues servicios ni precios que no te di."},{"tipo":"tabla","titulo":"Lo que toda cotización debe decir","encabezados":["Elemento","Por qué evita un pleito"],"filas":[["Qué NO incluye","Es la causa número uno de reclamos en el destino"],["Por persona o por habitación","Cambia el precio al doble o a la mitad"],["Ocupación (sencilla, doble, triple)","El hotel cobra por habitación, no por persona"],["Vigencia de la tarifa","Las tarifas cambian por temporada y disponibilidad"],["Anticipo y saldo","Define cuándo queda realmente apartado"],["Política de cancelación","Evita devoluciones que no puedes cubrir"]]},{"tipo":"excel","rotulo":"¿Cuánto te queda de este paquete?","datos":[["Concepto","Monto (MXN)"],["Hospedaje 3 noches",4200],["Traslados aeropuerto",1800],["Tour de día completo",1500],["Costo total",""],["Precio al cliente",9500],["Ganancia",""],["Margen",""]],"retos":[{"celda":"B5","formula":"=SUMA(B2:B4)","esperado":7500,"requiere":"SUMA(","texto":"<b>B5</b>: costo total de lo que le pagas a tus proveedores."},{"celda":"B7","formula":"=B6-B5","esperado":2000,"texto":"<b>B7</b>: ganancia = precio al cliente − costo total."},{"celda":"B8","formula":"=B7/B6","esperado":0.21052631578947367,"texto":"<b>B8</b>: margen = ganancia ÷ precio al cliente.","explica":"≈21%. Si das 10% de descuento para cerrar, tu margen baja a cerca de 12% y con una sola cancelación mal cobrada pierdes el paquete completo. Calcula antes de descontar."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA escribió «traslados incluidos» y tú no los cotizaste. Tú…","ops":["Lo corriges antes de enviar","Lo dejas, suena mejor","Lo dejas y los cobras aparte al llegar"],"correcta":0},{"p":"El precio del hotel para esas fechas lo obtienes de…","ops":["La tarifa confirmada por el hotel o el mayorista","Lo que calcule la IA","La tarifa que pagaste la temporada pasada"],"correcta":0},{"p":"Margen =","ops":["Ganancia ÷ precio al cliente","Precio al cliente ÷ costo","Precio al cliente − anticipo"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> una agencia en Oaxaca cotiza para 8 amigos 4 noches en Huatulco. El hotel le confirmó $2,400 por noche por habitación doble. La IA armó la cotización como «$2,400 por persona por noche» y agregó «desayuno incluido», que el hotel no confirmó."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Con 4 habitaciones dobles, el hospedaje por persona por noche es…","ops":["$2,400","$1,200","$4,800"],"correcta":1,"explica":"La tarifa es por habitación: $2,400 ÷ 2 = $1,200 por persona por noche."},{"p":"¿Qué haces con el desayuno?","ops":["Lo dejas, suena bien","Lo quitas o lo confirmas con el hotel antes de enviar","Lo cobras aparte al llegar"],"correcta":1,"explica":"Lo que no confirmaste no se ofrece."},{"p":"Para evitar el error, en el prompt indicas…","ops":["Si cada tarifa es por persona o por habitación y la ocupación","Solo el destino","Que la IA calcule los precios"],"correcta":0,"explica":"Sin ese dato, la IA supone."}]},{"tipo":"comparar","titulo":"Renglón de hospedaje","malTitulo":"Ambiguo","mal":"«Hospedaje: $2,400 con desayuno.»","bienTitulo":"Claro","bien":"«Hospedaje: 4 habitaciones dobles, 4 noches, $2,400 por habitación por noche ($1,200 por persona). Solo habitación, sin alimentos.»"},{"tipo":"reflexion","rotulo":"Tu renglón más confuso","pregunta":"¿Qué concepto de tus cotizaciones genera más dudas o reclamos? Reescríbelo aclarando unidad, ocupación y qué no incluye.","ayuda":"Concepto… / Así lo escribo ahora: …"},{"tipo":"clave","items":["Di siempre qué NO incluye y si es por persona o por habitación.","Tarifas y disponibilidad: del proveedor, nunca de la IA.","Calcula el margen antes de ofrecer descuento."]}],"c-ia-turismo-m1-l2":[{"tipo":"texto","texto":"En turismo gana quien responde primero. Una persona que pregunta por una habitación a las 10 de la noche normalmente escribe a tres lugares; si contestas mañana a mediodía, ya reservó en otro. La IA te deja listas las respuestas base para que solo ajustes fechas y precio."},{"tipo":"plantilla","rotulo":"Respuestas base para pegar","texto":"Escribe respuestas base para las 6 preguntas que más me llegan en [WhatsApp / plataforma de reservas / Messenger]: 1) disponibilidad para fechas, 2) precio y qué incluye, 3) formas de pago y anticipo, 4) horario de llegada y salida, 5) si se admiten mascotas o niños, 6) cómo llegar. Máximo 4 renglones cada una, con campos [FECHA], [PRECIO] y [NOMBRE] para que yo los complete. Tono cercano, mexicano, sin palabras rebuscadas."},{"tipo":"comparar","titulo":"Primera respuesta","malTitulo":"Fría y lenta","mal":"«Buenas tardes, sí hay disponibilidad. Saludos.»","bienTitulo":"Específica y con siguiente paso","bien":"«¡Hola, Karla! Sí tenemos habitación doble para el 14 y 15 de noviembre: $1,850 por noche con desayuno y estacionamiento. Para apartarla se deja $1,000 de anticipo. ¿Te la reservo?»"},{"tipo":"relacionar","rotulo":"Canal y qué cuidar","pares":[["WhatsApp","Mensajes cortos y respuesta en minutos"],["Plataforma de reservas","Responder dentro del sistema y respetar sus reglas"],["Correo a empresa","Formato formal con cotización adjunta"],["Comentario público en redes","Responder amable y pasar a mensaje privado"]]},{"tipo":"plantilla","rotulo":"Calificar la solicitud","texto":"Escribe 4 preguntas breves para calificar a quien pide una cotización de [tipo de viaje]: fechas exactas o flexibles, número de personas y edades, presupuesto aproximado por persona y qué es lo más importante para el grupo. Redáctalas de forma que no suenen a interrogatorio y que se puedan mandar en un solo mensaje de WhatsApp."},{"tipo":"reflexion","rotulo":"Tu tiempo de respuesta","pregunta":"¿Cuánto tardas hoy en contestar una solicitud fuera de horario y qué respuesta base te resolvería la mitad de los casos?","ayuda":"Hoy tardo… / La respuesta base que me falta es la de…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un hostal en San Cristóbal de las Casas usa respuestas base hechas con la IA. En la de mascotas escribió «¡Claro, somos pet friendly!», aunque el hostal no acepta mascotas. Un huésped llegó con su perro."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué falló?","ops":["El huésped","Nadie revisó la respuesta base contra las reglas reales del hostal","El WhatsApp"],"correcta":1,"explica":"Cada respuesta base se revisa una vez contra tus reglas antes de usarla."},{"p":"¿Qué haces con el huésped que ya llegó?","ops":["Lo rechazas sin más","Reconoces el error, buscas una solución razonable y cumples lo que el mensaje prometió o compensas","Le dices que debió preguntar"],"correcta":1,"explica":"El error fue del negocio; la solución también."},{"p":"Para que no se repita…","ops":["Corriges la respuesta base y la marcas como revisada","Dejas de usar respuestas base","Le pides a la IA que se acuerde"],"correcta":0,"explica":"Una biblioteca revisada es la que protege."}]},{"tipo":"comparar","titulo":"Respuesta base de mascotas","malTitulo":"Sin revisar","mal":"«¡Claro, somos pet friendly! Tráelo.»","bienTitulo":"Revisada","bien":"«Por ahora no recibimos mascotas. Si te sirve, cerca hay una pensión para perros que otros huéspedes nos han recomendado; te paso sus datos.»"},{"tipo":"reflexion","rotulo":"Tu respuesta base de riesgo","pregunta":"¿Qué respuesta base podría meterte en problemas si dice algo incorrecto (mascotas, niños, estacionamiento, accesibilidad)? Escríbela verificada.","ayuda":"Tema… / Respuesta verificada: …"},{"tipo":"clave","items":["Responde con dato concreto y un siguiente paso.","Una respuesta base por cada pregunta frecuente.","Califica antes de armar una cotización de horas."]}],"c-ia-turismo-m1-l3":[{"tipo":"destacado","texto":"<b>La política la decides tú, no la IA.</b> Cuánto anticipo pides, hasta cuándo se puede cancelar y si devuelves o das crédito para otra fecha son decisiones de tu negocio. La IA sirve para redactarlas en lenguaje claro y para que no se te olvide ningún caso, no para inventarte reglas ni para decirte qué dice la ley."},{"tipo":"plantilla","rotulo":"Políticas en lenguaje claro","texto":"Convierte estas reglas de mi negocio en un texto claro de máximo 150 palabras que pueda enviar por WhatsApp antes de cada reserva: anticipo de [%] para apartar; saldo a pagar [cuándo]; cancelación con más de [días] de anticipación: [qué pasa]; con menos de [días]: [qué pasa]; cambio de fecha: [regla]; hora de llegada [hora] y salida [hora]. Escríbelo en segunda persona, sin tecnicismos y sin agregar reglas que yo no puse."},{"tipo":"excel","rotulo":"Anticipo y saldo","datos":[["Concepto","Monto (MXN)"],["Total del paquete",18600],["Anticipo 30%",""],["Saldo",""]],"retos":[{"celda":"B3","formula":"=B2*0.3","esperado":5580,"texto":"<b>B3</b>: anticipo del 30% para apartar."},{"celda":"B4","formula":"=B2-B3","esperado":13020,"texto":"<b>B4</b>: saldo que queda por pagar.","explica":"$5,580 de anticipo y $13,020 de saldo. Escribe las dos cifras y la fecha límite del saldo en la confirmación: así nadie discute el día de la llegada."}]},{"tipo":"ordenar","rotulo":"Ordena la confirmación de una reserva","items":[{"frase":"confirmar-disponibilidad enviar-cotización recibir-anticipo mandar-confirmación-escrita recordar-un-día-antes","es":"De la consulta al recordatorio previo a la llegada"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un huésped apartó por WhatsApp sin que le mandaras la política. Llega y reclama. Lo que faltó fue…","ops":["Enviar la política por escrito antes de recibir el anticipo","Cobrarle más caro","Pedirle una reseña antes de llegar"],"correcta":0},{"p":"Le preguntas a la IA cuántos días de cancelación marca la ley para hoteles. Lo correcto es…","ops":["No tomarlo como dato legal y consultarlo con un abogado o tu cámara","Copiar lo que responda en tu política","Usar lo que hace la competencia sin revisarlo"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> la dueña de unas cabañas en Mazamitla dio sus reglas: anticipo de 50%, cancelación con más de 15 días: se devuelve el anticipo menos $500; con menos de 15 días: se da crédito para otra fecha. La IA redactó: «Cancela cuando quieras con reembolso del 100%»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué problema tiene el texto?","ops":["Ninguno, es amable","Cambió la política: promete un reembolso que la dueña no autorizó","Es muy largo"],"correcta":1,"explica":"La IA redacta; la política la decide el negocio."},{"p":"Un huésped cancela 20 días antes con un anticipo de $3,000. Según la política real, se le devuelve…","ops":["$3,000","$2,500","Nada"],"correcta":1,"explica":"Más de 15 días: anticipo menos $500."},{"p":"Si cancela 5 días antes…","ops":["Se le devuelve todo","Recibe crédito para otra fecha","Pierde todo sin aviso"],"correcta":1,"explica":"Menos de 15 días: crédito, según la política."}]},{"tipo":"comparar","titulo":"Texto de la política","malTitulo":"Redactado por la IA sin control","mal":"«Cancela cuando quieras con reembolso del 100%.»","bienTitulo":"Fiel a las reglas del negocio","bien":"«Para apartar se deja 50%. Si cancelas con más de 15 días, te devolvemos el anticipo menos $500. Con menos de 15 días, te damos crédito para otra fecha.»"},{"tipo":"reflexion","rotulo":"Tu política revisada","pregunta":"Escribe tu política de cancelación en 3 renglones claros y compárala con lo que hoy dicen tus mensajes. ¿Coinciden?","ayuda":"Mi política: … / Mis mensajes dicen: … / Corrijo…"},{"tipo":"clave","items":["Política por escrito ANTES del anticipo.","Anticipo, saldo y fecha límite con cifras exactas.","Recordatorio un día antes de la llegada."]}],"c-ia-turismo-m2-l1":[{"tipo":"texto","texto":"Un itinerario genérico («día 1: city tour») no vende. Lo que vende es un itinerario que se nota hecho para ese grupo: la pareja que quiere tranquilidad, la familia con un niño de 3 años, el grupo de 12 amigos con presupuesto apretado. La IA es muy buena armando la estructura hora por hora; tú pones los horarios reales, los precios vigentes y las distancias del destino que conoces."},{"tipo":"plantilla","rotulo":"Itinerario a la medida","texto":"Arma un itinerario de [número] días en [destino] para [perfil: pareja, familia con niños de X años, grupo de amigos, adulto mayor, viaje de empresa]. Presupuesto aproximado por persona: [monto] MXN. Ritmo: [tranquilo / intenso]. Usa solo estos lugares y actividades que yo conozco y ya verifiqué: [lista]. Formato por día: mañana, comida, tarde, noche, con tiempo estimado de traslado entre puntos y una opción de respaldo si llueve. Marca [VERIFICAR] junto a cualquier horario o precio que no te haya dado."},{"tipo":"destacado","texto":"<b>Horarios, precios y disponibilidad: siempre verificados.</b> La IA no sabe si ese museo cierra los lunes, si el tour subió de precio esta temporada o si la carretera está en obra. Antes de enviar el itinerario, confirma cada horario y cada tarifa con el proveedor o el sitio oficial. Un itinerario bonito con un museo cerrado te cuesta la reseña."},{"tipo":"relacionar","rotulo":"Perfil y qué priorizar","pares":[["Familia con niños pequeños","Traslados cortos y siesta a media tarde"],["Pareja en aniversario","Cena reservada y tiempo libre sin prisas"],["Grupo de amigos con poco presupuesto","Actividades gratuitas y comida local económica"],["Viaje de empresa","Horarios fijos y sede cerca del hotel"],["Adulto mayor","Poca caminata y baños disponibles en la ruta"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA puso 4 actividades en un mismo día en puntos alejados. Tú…","ops":["Reduces a lo que sí da tiempo con traslados reales","Lo dejas, se ve completo","Quitas los tiempos de traslado para que quepa"],"correcta":0},{"p":"El precio del tour que aparece en el itinerario…","ops":["Lo confirmas con el operador antes de enviarlo","Lo tomas del texto de la IA","Lo redondeas hacia abajo para que se vea atractivo"],"correcta":0},{"p":"Una opción de respaldo si llueve sirve para…","ops":["Salvar el día sin improvisar","Llenar espacio","Cobrar un cargo extra al grupo"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un operador en Mérida arma un día de cenotes para una familia con una abuela de 78 años. La IA propuso tres cenotes a los que se baja por escaleras largas, marcó uno como «abierto los lunes, entrada libre» y calculó 20 minutos entre dos puntos que están a más de una hora."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué ajustas primero por el perfil?","ops":["Cenotes con acceso fácil y pocas escaleras","Más cenotes para aprovechar","Nada"],"correcta":0,"explica":"El perfil manda: accesibilidad antes que cantidad."},{"p":"«Abierto los lunes, entrada libre»…","ops":["Se verifica con el cenote o su sitio oficial antes de enviar","Se deja","Se cambia a «abierto siempre»"],"correcta":0,"explica":"Horarios y precios cambian; se confirman."},{"p":"Los tiempos de traslado los tomas de…","ops":["La IA","Una herramienta de mapas y tu experiencia en la ruta","El cliente"],"correcta":1,"explica":"La IA no conoce distancias reales."}]},{"tipo":"comparar","titulo":"Día del itinerario","malTitulo":"Genérico","mal":"«Día 2: tres cenotes increíbles, entrada libre, todos cerca.»","bienTitulo":"Para este grupo","bien":"«Día 2: un cenote con acceso por rampa y área de descanso (horario y entrada confirmados el lunes), comida regional y regreso al hotel a las 4 p. m. para descansar.»"},{"tipo":"reflexion","rotulo":"Tu perfil más difícil","pregunta":"¿Qué perfil de viajero te cuesta más atender (adultos mayores, niños pequeños, personas con discapacidad)? Escribe 3 criterios que siempre aplicarías.","ayuda":"Perfil… / Criterio 1… / 2… / 3…"},{"tipo":"clave","items":["El itinerario se arma por perfil, no por destino.","Traslados y tiempos reales, no ideales.","[VERIFICAR] en todo horario o precio que no confirmaste."]}],"c-ia-turismo-m2-l2":[{"tipo":"texto","texto":"Casi toda reseña de una estrella empieza como un problema chico que nadie atendió a tiempo: el aire que no enfría, el desayuno que ya se acabó, el ruido del cuarto de al lado. La regla es simple: si el huésped te lo dice estando ahí, todavía es un problema de operación; si lo dice al irse, ya es un problema de reputación."},{"tipo":"plantilla","rotulo":"Mensajes de la estancia","texto":"Escribe mensajes breves y cálidos para: 1) bienvenida el día de la llegada con datos prácticos (clave de wifi, horarios de alimentos, contacto directo), 2) mensaje a media estancia preguntando si todo está bien, 3) recordatorio de salida con hora y opción de guardar equipaje, 4) agradecimiento el día de la salida. Máximo 4 renglones cada uno, con campos [NOMBRE], [HORA] y [CONTACTO]. Que suenen a persona, no a robot."},{"tipo":"plantilla","rotulo":"Respuesta a una queja en el momento","texto":"Un huésped se queja de [problema real]. Escribe qué le diría en persona y un mensaje de seguimiento: reconoce el problema sin excusas, di qué vamos a hacer y en cuánto tiempo, ofrece [compensación que yo decida] y cierra confirmando que quedó resuelto. Máximo 80 palabras. No prometas nada que no esté en la lista que te di."},{"tipo":"ordenar","rotulo":"Ordena el manejo de una queja","items":[{"frase":"escuchar disculparte resolver confirmar registrar","es":"Del reclamo al registro para que no se repita"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El aire acondicionado falla y no hay habitación para cambiar. Lo mejor es…","ops":["Avisar el tiempo real de reparación y ofrecer algo concreto","Decir que ya lo están viendo y no volver","Ofrecer una noche gratis sin consultar a nadie"],"correcta":0},{"p":"La IA propuso ofrecer una noche gratis como compensación. Tú…","ops":["Solo ofreces lo que tú autorizaste","Lo ofreces porque lo dijo la IA","Ofreces dos noches para asegurar la reseña"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu queja más repetida","pregunta":"¿Cuál es la queja que más te llega y qué respuesta y solución tendrías lista para la próxima vez?","ayuda":"La queja más común es… / Mi respuesta lista sería… / La solución que puedo ofrecer es…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> en un hotel boutique en Guanajuato capital, una pareja se queja a las 11 p. m. del ruido de una callejoneada. No hay habitaciones libres en la parte trasera. La IA sugiere responder: «Le regalamos la noche y una cena»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué puedes ofrecer?","ops":["Lo que autorizó la gerencia para estos casos: por ejemplo, tapones y cambio de habitación al día siguiente","Lo que propuso la IA","Nada, es la ciudad"],"correcta":0,"explica":"La compensación sale de tu lista autorizada."},{"p":"En tus mensajes previos a la llegada conviene…","ops":["Avisar que en el centro hay eventos nocturnos y qué habitaciones son más tranquilas","Ocultarlo","Prometer silencio total"],"correcta":0,"explica":"Lo que se avisa antes no se convierte en queja."},{"p":"La queja se registra para…","ops":["Detectar el patrón y ajustar la asignación de habitaciones","Nada","Culpar al recepcionista"],"correcta":0,"explica":"El registro te dice qué corregir."}]},{"tipo":"comparar","titulo":"Respuesta en el momento","malTitulo":"Sin control","mal":"«Le regalamos la noche y una cena.»","bienTitulo":"Dentro de lo autorizado","bien":"«Tiene razón, esta noche hay callejoneada hasta la medianoche. Le traigo tapones ahora y mañana le cambio a una habitación interior sin costo. ¿Le parece bien?»"},{"tipo":"reflexion","rotulo":"Tu lista de compensaciones","pregunta":"Escribe las 4 compensaciones que tu negocio autoriza, de menor a mayor, y quién puede aprobar cada una.","ayuda":"1. … aprueba… / 2. … / 3. … / 4. …"},{"tipo":"clave","items":["Problema resuelto en la estancia, no en la reseña.","Compensaciones: solo las que tú autorizas.","Registra cada queja para atacar la causa."]}],"c-ia-turismo-m2-l3":[{"tipo":"texto","texto":"Las reseñas son tu vendedor las 24 horas. Dos cosas mueven la aguja: pedirlas en el momento correcto (cuando el huésped está contento, no un mes después) y responder todas, sobre todo las malas. Quien lee tu perfil no está evaluando la queja: está evaluando cómo respondes."},{"tipo":"plantilla","rotulo":"Pedir la reseña","texto":"Escribe 3 versiones cortas para pedir una reseña a un huésped satisfecho: una para decirla en persona al momento de la salida, una para WhatsApp el mismo día y una para correo al día siguiente. Sin sonar a súplica, sin ofrecer nada a cambio, con el enlace [LIGA] y máximo 3 renglones cada una."},{"tipo":"plantilla","rotulo":"Responder una reseña negativa","texto":"Responde públicamente a esta reseña negativa [pegar texto de la reseña], sabiendo que lo que realmente pasó fue esto [tu versión verificada con el personal]. Reglas: agradece el comentario, reconoce lo que sí falló, di qué cambiaste o vas a cambiar, no discutas ni des detalles del huésped, invita a escribirnos a [correo o teléfono]. Máximo 90 palabras, tono sereno."},{"tipo":"comparar","titulo":"Respuesta a una reseña de 2 estrellas","malTitulo":"Defensiva","mal":"«Señor, usted llegó fuera de horario y no respetó las reglas. El hotel siempre está limpio, usted es el único que se ha quejado.»","bienTitulo":"Serena y útil para quien la lee","bien":"«Gracias por decírnoslo. Tiene razón en que la habitación no estaba lista a su llegada; ese día tuvimos un retraso en limpieza y ya ajustamos los horarios del turno. Nos gustaría escucharlo: puede escribirnos al 477…»"},{"tipo":"completar","rotulo":"Completa la regla de respuesta","instruccion":"Escribe la palabra que falta. Se vale cualquier palabra equivalente.","items":[{"frase":"Antes de responder una reseña negativa, verifico qué pasó con el ___ que estuvo en turno.","resp":["personal","equipo","colaborador","recepcionista","staff"],"pista":"La persona o el grupo que atendió ese día."},{"frase":"En la respuesta pública nunca escribo el número de habitación ni datos ___ del huésped.","resp":["personales","privados","sensibles","confidenciales"],"pista":"Lo contrario de públicos."},{"frase":"Una buena respuesta cierra invitando a seguir la conversación por un canal ___.","resp":["privado","directo","personal"],"pista":"Lo contrario de público."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La reseña dice algo que sabes que es falso. Lo mejor es…","ops":["Dar tu versión con respeto y sin atacar","Responder con sarcasmo","Pedir a la plataforma que la borre sin responder"],"correcta":0},{"p":"El mejor momento para pedir la reseña es…","ops":["Al final de la estancia, cuando el huésped está contento","Un mes después","Antes de que el huésped haga el check-in"],"correcta":0},{"p":"Ofrecer un descuento a cambio de una reseña de 5 estrellas…","ops":["Es mala práctica y puede violar las reglas de la plataforma","Es lo normal","Está bien si el descuento es pequeño"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un huésped dejó 2 estrellas diciendo que la regadera no calentaba. La IA redactó la respuesta: «Estimado huésped de la habitación 12: según nuestras cámaras, usted llegó a las 2 a. m. y el calentador funcionaba»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué dato no debe aparecer en la respuesta pública?","ops":["El número de habitación y lo que muestran las cámaras","El agradecimiento","La invitación a escribir"],"correcta":0,"explica":"En público no se exponen datos del huésped."},{"p":"Antes de responder, verificas…","ops":["Con mantenimiento y el turno si el calentador tuvo falla ese día","Nada","Con la IA"],"correcta":0,"explica":"Tu versión debe estar confirmada."},{"p":"El tono correcto es…","ops":["Defensivo","Sereno: reconoces lo que sí falló y explicas qué harás","Irónico"],"correcta":1,"explica":"Quien lee evalúa cómo respondes."}]},{"tipo":"comparar","titulo":"Respuesta a la reseña de la regadera","malTitulo":"Expone al huésped","mal":"«Estimado huésped de la habitación 12: según nuestras cámaras, usted llegó a las 2 a. m.»","bienTitulo":"Serena y privada","bien":"«Gracias por avisarnos. Ese día el calentador tuvo una falla que ya reparamos y ahora lo revisamos cada mañana. Nos gustaría escucharle: escríbanos a reservas@…»"},{"tipo":"reflexion","rotulo":"Tu respuesta pendiente","pregunta":"Elige una reseña negativa reciente (tuya o de un negocio similar) y escribe una respuesta de máximo 80 palabras sin datos del huésped.","ayuda":"Respuesta: …"},{"tipo":"clave","items":["Pide la reseña en el momento de mayor satisfacción.","Responde todas, sobre todo las negativas.","Nunca compres reseñas ni expongas datos del huésped."]}],"c-ia-turismo-m3-l1":[{"tipo":"texto","texto":"Nadie viaja a un lugar que no conoce. Tu trabajo no es solo vender tu hotel o tu tour: es hacer que la gente quiera ir a tu destino. La IA resuelve lo que más cuesta, que es mantener el ritmo: un calendario con ideas, textos y pies de foto listos para todo el mes."},{"tipo":"plantilla","rotulo":"Calendario de contenidos del destino","texto":"Arma un calendario de contenidos de 4 semanas para [tipo de negocio] en [destino], con 3 publicaciones por semana. Mezcla estos temas: qué hacer en el destino, comida típica, recomendaciones prácticas (clima, qué llevar, cómo llegar), detrás de cámaras del equipo y una oferta al mes. Para cada publicación: idea, formato (foto, carrusel, video corto), texto de máximo 4 renglones, 5 etiquetas y qué foto o video necesito grabar. Considera estas fechas locales que sí existen: [fiestas o temporadas que tú conoces]."},{"tipo":"plantilla","rotulo":"Descripción para plataformas de reserva","texto":"Escribe la descripción de mi [hotel / cabaña / tour] para una plataforma de reservas con estos datos verificados: [ubicación, capacidad, servicios, qué hay cerca, reglas]. Estructura: 1) primera frase que enganche, 2) el espacio y sus servicios, 3) qué hay alrededor con distancias reales, 4) para quién es ideal y para quién no, 5) reglas de la casa. No exageres ni menciones servicios que no te di. Escribe también una versión corta de 200 caracteres."},{"tipo":"destacado","texto":"<b>Fotos reales, siempre.</b> La IA puede mejorar la luz de una foto o sugerir encuadres, pero una imagen generada o retocada que muestre una alberca, una vista o un cuarto que no existe garantiza dos cosas: huéspedes molestos al llegar y reseñas de una estrella. Si usas alguna imagen ilustrativa del destino y no de tu propiedad, dilo claramente en el pie de foto."},{"tipo":"relacionar","rotulo":"Formato y para qué sirve","pares":[["Video corto vertical","Mostrar el lugar en movimiento y llegar a gente nueva"],["Carrusel de fotos","Enseñar todos los espacios en una sola publicación"],["Publicación de recomendaciones","Ganar confianza como quien conoce el destino"],["Ficha en plataforma de reserva","Convertir al que ya está listo para reservar"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"«A 5 minutos de la playa» sin haberlo medido…","ops":["Se verifica o se cambia por la distancia real","Se deja, vende mejor","Se cambia a «cerca de todo»"],"correcta":0},{"p":"Una foto generada con IA de una alberca que no tienes…","ops":["Provoca reclamos y reseñas negativas","Atrae más reservas sin riesgo","Se permite si la foto es muy parecida a la real"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> la IA armó el calendario de marzo de un hotel en Pátzcuaro e incluyó «el Festival de la Mariposa Dorada, 12 de marzo», que nadie en el pueblo conoce, y el texto «a 2 minutos a pie de la plaza», sin medir."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué haces con el festival?","ops":["Lo publicas","Lo verificas con fuentes locales; si no existe, lo quitas","Lo cambias de fecha"],"correcta":1,"explica":"Una fecha falsa te cuesta credibilidad."},{"p":"«A 2 minutos a pie»…","ops":["Se mide caminando o en el mapa y se escribe lo real","Se deja","Se cambia a «a un paso»"],"correcta":0,"explica":"Distancias reales, siempre."},{"p":"En el prompt del calendario debiste…","ops":["Darle solo fechas locales que tú confirmaste","Pedirle que invente eventos","Dejarlo libre"],"correcta":0,"explica":"Lo que no le das, lo inventa."}]},{"tipo":"comparar","titulo":"Publicación del calendario","malTitulo":"Sin verificar","mal":"«¡No te pierdas el Festival de la Mariposa Dorada este 12 de marzo, a 2 minutos del hotel!»","bienTitulo":"Verificada","bien":"«Este fin de semana hay tianguis de artesanías en la plaza, a 6 minutos caminando del hotel. Pregúntanos por el recorrido de talleres de la zona.»"},{"tipo":"reflexion","rotulo":"Tus fechas reales","pregunta":"Escribe 5 fechas o eventos reales de tu destino para los próximos 3 meses y dónde confirmaste cada uno.","ayuda":"1. … confirmado en… / 2. … / 3. … / 4. … / 5. …"},{"tipo":"clave","items":["Promueve el destino, no solo tu propiedad.","Distancias y servicios: reales y verificados.","Imagen ilustrativa, siempre señalada como tal."]}],"c-ia-turismo-m3-l2":[{"tipo":"texto","texto":"En hotelería casi todo se decide con tres números: <b>ocupación</b> (qué porcentaje de tus noches disponibles vendiste), <b>tarifa promedio</b> (cuánto cobraste en promedio por noche vendida) e <b>ingreso por habitación disponible</b> (cuánto te dejó cada habitación, se haya vendido o no). Excel los calcula; la IA te ayuda a interpretarlos y a decidir qué mover."},{"tipo":"excel","rotulo":"Tus números del mes","datos":[["Concepto","Valor"],["Noches disponibles en el mes",300],["Noches vendidas",201],["Ingreso por habitaciones (MXN)",281400],["Ocupación",""],["Tarifa promedio por noche",""],["Ingreso por noche disponible",""]],"retos":[{"celda":"B5","formula":"=B3/B2","esperado":0.67,"texto":"<b>B5</b>: ocupación = noches vendidas ÷ noches disponibles."},{"celda":"B6","formula":"=B4/B3","esperado":1400,"texto":"<b>B6</b>: tarifa promedio = ingreso ÷ noches vendidas."},{"celda":"B7","formula":"=B4/B2","esperado":938,"texto":"<b>B7</b>: ingreso por noche disponible = ingreso ÷ noches disponibles.","explica":"67% de ocupación, $1,400 de tarifa promedio y $938 por noche disponible. Si bajas la tarifa a $1,200 y la ocupación solo sube a 72%, el ingreso por noche disponible queda en $864: vendiste más y ganaste menos."}]},{"tipo":"plantilla","rotulo":"Decidir una promoción con datos","texto":"Estos son mis números ya calculados del mes [ocupación, tarifa promedio, ingreso por noche disponible] y estos los del mismo mes del año pasado [datos]. Mis días flojos son [días] y mi temporada baja es [meses]. Ayúdame a razonar 3 opciones para llenar los días flojos sin destruir mi tarifa promedio (por ejemplo, valor agregado en lugar de descuento) y dime qué dato debería revisar para saber si funcionó. No inventes cifras ni promedios de la industria."},{"tipo":"tabla","titulo":"Qué mover antes de bajar el precio","encabezados":["Palanca","Ejemplo"],"filas":[["Valor agregado","Desayuno o salida tardía incluida en lugar de descuento"],["Mínimo de noches","Tarifa especial solo si se quedan 2 noches entre semana"],["Paquete","Hospedaje más tour a un precio conjunto"],["Público distinto","Empresas o grupos para los días flojos"],["Descuento directo","La última opción: baja tu tarifa promedio todo el mes"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Ocupación =","ops":["Noches vendidas ÷ noches disponibles","Ingreso ÷ noches vendidas","Ingreso ÷ noches disponibles"],"correcta":0},{"p":"Vender más noches a menor precio…","ops":["No siempre deja más dinero","Siempre es mejor","Nunca conviene en temporada baja"],"correcta":0},{"p":"Antes de bajar el precio conviene probar…","ops":["Valor agregado o mínimo de noches","Cerrar el hotel","Subir la tarifa de fin de semana"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> un hotel de 20 habitaciones en Valle de Bravo tuvo en octubre 62% de ocupación con tarifa promedio de $1,900. La IA sugiere «bajar la tarifa a $1,500 porque así la ocupación subirá a 85%», sin ningún dato que lo respalde."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué haces con el 85%?","ops":["Lo tomas como promesa","Lo tratas como supuesto sin base y lo contrastas con tu historial","Lo publicas"],"correcta":1,"explica":"Nadie sabe cuánto subirá la ocupación: es una apuesta."},{"p":"Con 62% y $1,900, el ingreso por noche disponible es aprox…","ops":["$1,178","$1,900","$3,064"],"correcta":0,"explica":"0.62 × 1,900 = $1,178."},{"p":"Si bajas a $1,500 y llegas a 70%, el ingreso por noche disponible…","ops":["Sube","Baja a $1,050","Queda igual"],"correcta":1,"explica":"0.70 × 1,500 = $1,050: vendes más y ganas menos."}]},{"tipo":"comparar","titulo":"Recomendación a la dueña","malTitulo":"Sin datos","mal":"«Bajemos a $1,500, la ocupación subirá a 85%.»","bienTitulo":"Con números y prueba","bien":"«Hoy dejamos $1,178 por noche disponible. Propongo probar un paquete de 2 noches entre semana con desayuno a $1,800 por noche durante un mes y medir ocupación e ingreso por noche disponible.»"},{"tipo":"reflexion","rotulo":"Tu decisión de precio","pregunta":"Piensa en tu última promoción. Escribe cuál fue tu ingreso por noche disponible (o por lugar disponible) antes y después. ¿Funcionó?","ayuda":"Antes… / Después… / Conclusión…"},{"tipo":"clave","items":["Ocupación, tarifa promedio e ingreso por noche disponible.","Más ocupación no siempre es más dinero.","El descuento directo es la última palanca."]}],"c-ia-turismo-m3-l3":[{"tipo":"destacado","texto":"<b>El caso:</b> una posada de 10 habitaciones en un pueblo cerca de Puebla llena fines de semana y vacaciones, pero de martes a jueves su ocupación baja a 25%. Tarda hasta 12 horas en contestar WhatsApp, no pide reseñas y su perfil en plataformas tiene fotos de hace cuatro años. La dueña quiere subir la ocupación entre semana sin regalar el hotel."},{"tipo":"pasos","rotulo":"Resuélvelo con la IA","pasos":["<b>Números (M3 L2):</b> calcula ocupación, tarifa promedio e ingreso por noche disponible del último trimestre en Excel.","<b>Palancas (M3 L2):</b> antes de descontar, arma un paquete entre semana con valor agregado y mínimo de 2 noches.","<b>Público nuevo (M1 L2):</b> respuestas base y cotización para empresas y grupos que sí pueden viajar en martes.","<b>Cotización (M1 L1):</b> paquete con qué incluye, qué no incluye, anticipo y política.","<b>Promoción (M3 L1):</b> calendario de 4 semanas mostrando el pueblo, con fotos nuevas y reales.","<b>Estancia y reseñas (M2 L2, L3):</b> mensajes de bienvenida y de salida, y petición de reseña el día de la salida."]},{"tipo":"practica","rotulo":"Decisiones del caso","preguntas":[{"p":"Para llenar martes y miércoles, la primera opción debería ser…","ops":["Un paquete con valor agregado para empresas y grupos","Bajar la tarifa 40% todo el mes","Cerrar esas noches para ahorrar personal"],"correcta":0},{"p":"Las fotos del perfil tienen 4 años y ya remodelaron. Lo correcto es…","ops":["Tomar fotos nuevas reales de la propiedad","Generar imágenes con IA del cuarto ideal","Dejar las fotos anteriores hasta la siguiente temporada"],"correcta":0},{"p":"Tarda 12 horas en contestar WhatsApp. La solución más rápida es…","ops":["Respuestas base listas para las 6 preguntas frecuentes","Cerrar el WhatsApp","Contestar solo los mensajes con fechas"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu temporada baja","pregunta":"¿Cuáles son tus días o meses flojos y qué paquete con valor agregado (sin descuento directo) podrías ofrecer la próxima semana?","ayuda":"Mis días flojos son… / El paquete que ofrecería incluye… / El precio sería…"},{"tipo":"destacado","texto":"<b>¡Terminaste el curso!</b> La IA te da velocidad para cotizar, responder, promover y atender; lo que sostiene el negocio es que cada precio, cada horario y cada foto correspondan a la realidad que el huésped se va a encontrar al llegar."},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>El caso:</b> la posada del caso ya lanzó su paquete entre semana. Para acelerar, la IA le sugiere a la dueña «pedir a familiares y amigos que dejen reseñas de 5 estrellas» y «publicar fotos de la alberca del hotel vecino como si fueran propias»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Pedir reseñas a familiares que no se hospedaron…","ops":["Es mala práctica y puede violar las reglas de la plataforma","Es una buena idea","Está bien si son pocas"],"correcta":0,"explica":"Las reseñas deben venir de huéspedes reales."},{"p":"¿Qué haces con las fotos de la alberca vecina?","ops":["Las usas","No las usas: muestras solo lo que el huésped encontrará","Las usas sin decir nada"],"correcta":1,"explica":"Una foto engañosa garantiza reclamos."},{"p":"La forma legítima de juntar reseñas más rápido es…","ops":["Pedirla el día de la salida a cada huésped satisfecho","Comprarlas","Escribirlas tú"],"correcta":0,"explica":"Constancia en pedir, no atajos."}]},{"tipo":"comparar","titulo":"Plan para reseñas","malTitulo":"Atajo","mal":"«Que la familia deje 20 reseñas de 5 estrellas esta semana.»","bienTitulo":"Legítimo","bien":"«Pedir la reseña en persona el día de la salida y por WhatsApp esa tarde con la liga directa, a cada huésped del paquete entre semana.»"},{"tipo":"reflexion","rotulo":"Tu plan de reseñas","pregunta":"Escribe cómo y cuándo pedirás reseñas a partir de mañana, y quién del equipo lo hará.","ayuda":"Momento… / Canal… / Responsable… / Meta del mes…"},{"tipo":"clave","titulo":"Tu kit turístico con IA","items":["Cotizaciones completas, respuesta en minutos y políticas por escrito.","Itinerarios por perfil, estancia atendida y reseñas respondidas.","Promoción honesta del destino y decisiones con ocupación y tarifa."]}],"c-ia-turismo-m4-l1":[{"tipo":"texto","texto":"Cuando un grupo o una boda aparta habitaciones, el hotel suele dar un <b>bloqueo</b>: un número de habitaciones reservadas a una tarifa especial hasta una <b>fecha de liberación</b>. Después de esa fecha, lo que no se confirmó regresa a la venta o genera cargos, según el contrato. El trabajo es vigilar cuántas se han confirmado y avisar a tiempo. La IA te ayuda a armar la lista de habitaciones, los recordatorios y los mensajes; las condiciones salen del contrato con el hotel."},{"tipo":"destacado","texto":"<b>El caso:</b> una agencia en Guadalajara organiza una boda en Puerto Vallarta. Bloqueó 40 habitaciones; el contrato dice que si a la fecha de liberación hay menos de 80% confirmado, las no confirmadas se liberan sin cargo, y si quieren conservarlas hay que renegociar."},{"tipo":"excel","rotulo":"Seguimiento del bloqueo","datos":[["Semana","Bloqueadas","Confirmadas"],["8 semanas antes",40,14],["6 semanas antes",40,22],["4 semanas antes",40,29],["Decisión","",""]],"retos":[{"celda":"B5","formula":"=SI(C4/B4<0.8,\"Liberar o renegociar\",\"Mantener bloqueo\")","esperado":"Liberar o renegociar","texto":"<b>B5</b>: con SI, si el confirmado a 4 semanas (C4 ÷ B4) es menor a 0.8 escribe «Liberar o renegociar»; si no, «Mantener bloqueo».","requiere":"SI(","pista":"=SI(C4/B4<0.8,«Liberar o renegociar»,«Mantener bloqueo») con comillas rectas","explica":"Van 29 de 40, es decir 72.5%: toca hablar con los novios y el hotel antes de la fecha de liberación, no después."}]},{"tipo":"plantilla","rotulo":"Lista de habitaciones y recordatorios","texto":"Organiza esta lista de invitados que ya confirmaron hospedaje (solo nombre de pila e inicial, tipo de habitación, noches) en una tabla por tipo de habitación y fechas de llegada. Después redacta: 1) recordatorio para quienes no han confirmado con la fecha límite [fecha], 2) mensaje a los novios con el avance, 3) correo al hotel pidiendo confirmar la fecha de liberación. No cambies tarifas ni condiciones: usa solo las del contrato que te pego [condiciones]."},{"tipo":"destacado","texto":"<b>Errores comunes de la IA con grupos:</b> inventar condiciones de contrato («el hotel suele dar 30 días de gracia»), sumar mal habitaciones por tipo y mezclar tarifas por persona y por habitación. Las condiciones del bloqueo se leen en el contrato firmado, no se suponen."},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"La IA dice que «normalmente los hoteles no cobran las habitaciones no usadas». Tú…","ops":["Le crees","Revisas el contrato del bloqueo","Se lo dices a los novios"],"correcta":1,"explica":"Cada contrato tiene sus propias condiciones."},{"p":"A 4 semanas llevas 72.5% confirmado. Lo oportuno es…","ops":["Esperar a la fecha de liberación","Hablar ya con los novios y el hotel","Confirmar todas por tu cuenta"],"correcta":1,"explica":"Antes de la fecha tienes opciones; después, no."}]},{"tipo":"clave","items":["Bloqueo + fecha de liberación = seguimiento semanal.","Condiciones del contrato, nunca supuestas.","Datos mínimos de los invitados en la IA."]}],"c-ia-turismo-m4-l2":[{"tipo":"texto","texto":"Un tour tiene costos <b>fijos</b> (camioneta, guía, combustible: se pagan salga con 3 o con 12 personas) y <b>variables</b> (entradas, comida, seguro por persona). Con esos dos datos y tu precio sabes cuántas personas necesitas para no perder: el <b>punto de equilibrio</b>. La IA te ayuda a no olvidar costos y a redactar la ficha; la hoja de cálculo hace las cuentas."},{"tipo":"destacado","texto":"<b>El caso:</b> un operador en San Miguel de Allende quiere lanzar un recorrido a viñedos. Costos fijos por salida: $4,800. Costo variable por persona: $350. Precio: $950 por persona."},{"tipo":"excel","rotulo":"Punto de equilibrio del tour","datos":[["Concepto","Valor (MXN)"],["Costos fijos por salida",4800],["Costo variable por persona",350],["Precio por persona",950],["Personas para no perder",""],["Personas en la salida",12],["Ganancia de la salida",""]],"retos":[{"celda":"B5","formula":"=B2/(B4-B3)","esperado":8,"texto":"<b>B5</b>: punto de equilibrio = costos fijos ÷ (precio − costo variable)."},{"celda":"B7","formula":"=B6*(B4-B3)-B2","esperado":2400,"texto":"<b>B7</b>: ganancia con 12 personas = personas × (precio − variable) − fijos.","pista":"=B6*(B4-B3)-B2","explica":"Con 8 personas no pierdes ni ganas; con 12 ganas $2,400. Por eso la ficha del tour debe decir «mínimo 8 personas» y qué pasa si no se llega."}]},{"tipo":"destacado","texto":"<b>Permisos y requisitos: verifica el requisito vigente.</b> Guías acreditados, seguros para pasajeros, permisos para áreas naturales protegidas o para transporte turístico dependen de la actividad y el lugar. Verifica el requisito vigente con la autoridad correspondiente; la IA no sabe qué te aplica."},{"tipo":"plantilla","rotulo":"Ficha del tour","texto":"Redacta la ficha de mi tour [nombre] con estos datos verificados: duración, punto de salida, qué incluye, qué no incluye, qué llevar, nivel de esfuerzo, mínimo de [número] personas y qué pasa si no se alcanza (cambio de fecha o reembolso), política de cancelación [la mía]. Tono claro, máximo 200 palabras. No agregues requisitos legales, horarios ni precios que no te di."},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"Si sube el costo de la camioneta, el punto de equilibrio…","ops":["Sube","Baja","No cambia"],"correcta":0,"explica":"Más costos fijos = más personas para no perder."},{"p":"La IA dice que «para ese recorrido no necesitas ningún permiso». Tú…","ops":["Le crees","Verificas el requisito vigente con la autoridad correspondiente","Lo pones en la ficha"],"correcta":1,"explica":"Los permisos dependen de la actividad y el lugar."}]},{"tipo":"reflexion","rotulo":"Tu producto","pregunta":"Elige un tour, paquete o experiencia que vendas. Anota sus costos fijos, variables y precio. ¿Cuál es tu mínimo para no perder?","ayuda":"Fijos… / Variables por persona… / Precio… / Mínimo…"},{"tipo":"clave","items":["Punto de equilibrio = fijos ÷ (precio − variable).","La ficha dice el mínimo y qué pasa si no se alcanza.","Permisos y seguros: verifica el requisito vigente."]}],"c-ia-turismo-m4-l3":[{"tipo":"texto","texto":"La IA traduce rápido y con buen tono, y eso abre la puerta a huéspedes que no hablan español. El riesgo está en los detalles: una política que en la traducción se vuelve más generosa, un «no incluye» que se pierde o una cifra que cambia de formato. Para mensajes del día a día basta revisar; para políticas, contratos o condiciones de pago, compara la traducción con el original frase por frase o pide que la revise alguien que domine el idioma."},{"tipo":"destacado","texto":"<b>El caso:</b> un hotel en Tulum recibe muchas reservas de huéspedes de habla inglesa. Tradujo su política con la IA y la versión en inglés dice «full refund at any time», cuando la original dice «reembolso total con 7 días de anticipación»."},{"tipo":"plantilla","rotulo":"Traducir y verificar","texto":"Traduce al [idioma] este mensaje para un huésped: [texto]. Reglas: conserva exactamente cifras, fechas, horarios y condiciones; no agregues beneficios ni cambies el sentido de ninguna restricción. Después, haz una retrotraducción al español para que yo compare frase por frase, y marca con [REVISAR] cualquier término que pueda entenderse de dos formas."},{"tipo":"comparar","titulo":"Política traducida","malTitulo":"Traducción que cambia el sentido","mal":"«Full refund at any time.»","bienTitulo":"Fiel al original","bien":"«Full refund if you cancel at least 7 days before arrival.»"},{"tipo":"destacado","texto":"<b>Errores comunes de la IA al traducir en turismo:</b> suavizar restricciones, cambiar formatos de fecha (día/mes contra mes/día), convertir monedas sin que se lo pidas y omitir el «no incluye». Revisa siempre cifras, fechas y condiciones en la retrotraducción."},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"Para verificar una política traducida…","ops":["Confías en la IA","Pides retrotraducción y comparas frase por frase, o la revisa alguien que domine el idioma","La mandas y ves qué pasa"],"correcta":1,"explica":"Las condiciones no se dejan a la suerte."},{"p":"Un huésped te manda por chat la foto de su pasaporte para el registro. Tú…","ops":["La pegas en la IA para que la lea","La manejas solo en tu sistema de registro, nunca en una IA pública","La reenvías al grupo del equipo"],"correcta":1,"explica":"Documentos de identidad solo en tus sistemas autorizados."}]},{"tipo":"clave","items":["Traduce con reglas: cifras y condiciones intactas.","Retrotraducción o revisión humana para políticas.","Documentos de identidad, fuera de la IA."]}],"c-ia-turismo-m5-l1":[{"tipo":"texto","texto":"Eres gerente de un hotel boutique de 14 habitaciones en San Miguel de Allende y usas un asistente de IA todo el día. En cada escena hay <b>al menos un error</b> plantado. Encuéntralo antes de que llegue a un huésped, a una plataforma o a tu dueño."},{"tipo":"destacado","texto":"<b>Escena 1 — 9:00 a. m. Cotización de grupo.</b> La IA armó la cotización de 6 habitaciones para una boda: «6 habitaciones × 2 noches × $3,200 = $32,400, traslados incluidos». Tú no cotizaste traslados."},{"tipo":"reflexion","rotulo":"Escena 1: ¿qué corriges?","pregunta":"Rehaz la cuenta y di qué quitas o confirmas antes de enviar.","ayuda":"Cuenta correcta: … / Traslados: … / Antes de enviar reviso…"},{"tipo":"destacado","texto":"<b>Escena 2 — 11:30 a. m. Huésped internacional.</b> Una huésped canadiense pregunta por la política de cancelación. La traducción de la IA dice «free cancellation up to 24 hours before», y tu política es 7 días."},{"tipo":"reflexion","rotulo":"Escena 2: ¿qué corriges?","pregunta":"Reescribe la frase en inglés fiel a tu política y explica cómo verificarás traducciones de aquí en adelante.","ayuda":"Frase correcta: … / Verifico con…"},{"tipo":"destacado","texto":"<b>Escena 3 — 3:00 p. m. Promoción.</b> Para la publicación del fin de semana, la IA generó una imagen de una terraza con alberca «para inspirar» y escribió «a 2 minutos del Jardín Principal». El hotel no tiene alberca y nadie ha medido la distancia."},{"tipo":"reflexion","rotulo":"Escena 3: ¿qué corriges?","pregunta":"¿Qué cambias en la imagen y en el texto para que la publicación sea honesta y siga vendiendo?","ayuda":"Imagen: … / Distancia: … / Mensaje final: …"},{"tipo":"destacado","texto":"<b>Escena 4 — 7:00 p. m. Registro y reseña.</b> Recepción pegó en la IA fotos de pasaportes de 3 huéspedes «para que llene el registro». Además, la IA respondió una reseña negativa mencionando el número de habitación y el horario de llegada del huésped."},{"tipo":"reflexion","rotulo":"Escena 4: ¿qué corriges?","pregunta":"¿Qué reglas de datos se rompieron y cómo corriges la respuesta a la reseña?","ayuda":"Regla rota 1: … / Regla rota 2: … / Respuesta corregida: …"},{"tipo":"practica","rotulo":"Revisión del día","preguntas":[{"p":"6 habitaciones × 2 noches × $3,200 es…","ops":["$32,400","$38,400","$19,200"],"correcta":1,"explica":"6 × 2 × 3,200 = 38,400. Los cálculos van en tu hoja."},{"p":"La política traducida debe…","ops":["Decir lo mismo que el original, con los mismos días","Ser más flexible para atraer extranjeros","Omitir la cancelación"],"correcta":0,"explica":"Una traducción no cambia condiciones."},{"p":"Una imagen de alberca que no existe…","ops":["Se publica «para inspirar»","No se usa: muestras la propiedad real","Se usa si es pequeña"],"correcta":1,"explica":"Lo que muestras es lo que prometes."}]},{"tipo":"clave","items":["Cuentas en tu hoja; servicios solo si están confirmados.","Traducciones fieles, promoción honesta.","Datos e identificaciones de huéspedes, fuera de la IA."]}],"c-ia-turismo-m5-l2":[{"tipo":"texto","texto":"Convierte el curso en un <b>kit que uses desde mañana</b>. Responde cada paso con tu negocio, tus tarifas y tu destino reales (sin datos de huéspedes)."},{"tipo":"reflexion","rotulo":"Paso 1: tu biblioteca de prompts","pregunta":"Elige los 5 prompts del curso que más usarás (cotización, respuestas base, políticas, itinerario, quejas, reseñas, calendario, ficha de tour, bloqueo de grupo, traducción) y adáptalos a tu negocio.","ayuda":"1. … 2. … 3. … 4. … 5. …"},{"tipo":"reflexion","rotulo":"Paso 2: tu política de datos","pregunta":"Escribe tus 5 reglas: qué nunca pegas en una IA (identificaciones, tarjetas, teléfonos y datos de huéspedes), cómo nombras a los huéspedes en tus prompts y qué herramienta está autorizada.","ayuda":"Nunca pego… / Uso [NOMBRE]… / Herramienta autorizada: …"},{"tipo":"reflexion","rotulo":"Paso 3: tu lista de verificación","pregunta":"Escribe 6 puntos que revisas antes de enviar cualquier cotización, mensaje o publicación hecha con IA.","ayuda":"□ ¿Tarifas confirmadas y por persona o por habitación? □ ¿Qué no incluye? □ ¿Política igual a la real, también en otro idioma? □ ¿Horarios, distancias y eventos verificados? □ ¿Fotos reales? □ ¿Sin datos del huésped? …"},{"tipo":"reflexion","rotulo":"Paso 4: tu entregable real","pregunta":"Produce un entregable real: tu biblioteca de respuestas base revisada, una cotización tipo, la ficha de un tour o tu calendario del mes verificado. Pega la versión final.","ayuda":"Entregable: … / Lo uso a partir del…"},{"tipo":"plantilla","rotulo":"Índice de tu kit turístico","texto":"KIT TURÍSTICO CON IA — [tu nombre] — [negocio y destino] — [fecha]\n\n1. Respuestas base revisadas: [ ]\n2. Biblioteca de prompts: cotización [ ], itinerario [ ], quejas [ ], reseñas [ ], calendario [ ], traducción [ ]\n3. Políticas por escrito (anticipo, cancelación, cambios) en español y otros idiomas: [ ]\n4. Política de datos y herramienta autorizada: [ ]\n5. Lista de compensaciones autorizadas: [ ]\n6. Lista de verificación: [ ]\n7. Números: ocupación, tarifa promedio, ingreso por noche disponible [ ]\n8. Entregable real: [ ]\n9. Próxima revisión del kit: [fecha]","nota":"Actualízala cuando cambien tus tarifas, tus políticas o tu temporada."},{"tipo":"clave","items":["Prompts y respuestas base adaptados a tu negocio.","Política de datos, compensaciones y lista de verificación.","Un entregable real listo para usar."]}]},"q":{"c-ia-turismo-m1":[{"p":"El error más común en una cotización de viaje es…","ops":["No decir qué NO incluye","Usar letra grande","Mandarla en PDF","Poner el logo"],"correcta":0},{"p":"Margen =","ops":["Ganancia ÷ precio al cliente","Precio × costo","Costo ÷ ganancia","Precio − anticipo"],"correcta":0},{"p":"Las tarifas y la disponibilidad salen de…","ops":["El hotel, el mayorista o tu sistema","La IA","Una red social","Un cálculo aproximado"],"correcta":0},{"p":"Una primera respuesta efectiva incluye…","ops":["Dato concreto y un siguiente paso","Solo un saludo","El catálogo completo","Una disculpa"],"correcta":0},{"p":"Al cotizar hospedaje hay que aclarar…","ops":["Si el precio es por persona o por habitación","El color del edificio","La marca del camión","Nada"],"correcta":0},{"p":"La política de cancelación se envía…","ops":["Antes de recibir el anticipo","Al llegar el huésped","Al cancelar","Nunca"],"correcta":0},{"p":"Si el paquete cuesta $18,600 y el anticipo es 30%, el saldo es…","ops":["$13,020","$5,580","$18,600","$9,300"],"correcta":0},{"p":"Si la IA te dice qué exige la ley sobre cancelaciones…","ops":["Lo verificas con un abogado antes de usarlo","Lo copias tal cual","Lo publicas","Lo ignoras todo"],"correcta":0}],"c-ia-turismo-m2":[{"p":"Un itinerario se arma a partir de…","ops":["El perfil de quien viaja","El destino de moda","El clima del año pasado","El catálogo completo"],"correcta":0},{"p":"Los horarios de museos y tours…","ops":["Se verifican con el proveedor o el sitio oficial","Los da la IA","Se calculan","No importan"],"correcta":0},{"p":"Para una familia con niños pequeños conviene…","ops":["Traslados cortos y descanso a media tarde","Rutas de caminata larga","Cenas tardías","Vida nocturna"],"correcta":0},{"p":"Una queja atendida durante la estancia…","ops":["Evita una reseña negativa","No sirve de nada","Se olvida","Es un gasto"],"correcta":0},{"p":"Las compensaciones al huésped las define…","ops":["El negocio, no la IA","La IA","El huésped","La plataforma"],"correcta":0},{"p":"La reseña se pide…","ops":["Al final de la estancia","Antes de llegar","Un año después","Nunca"],"correcta":0},{"p":"Al responder una reseña negativa NO se debe…","ops":["Exponer datos del huésped ni discutir","Agradecer","Reconocer la falla","Invitar al contacto directo"],"correcta":0},{"p":"Dar un descuento a cambio de 5 estrellas es…","ops":["Mala práctica y riesgo con la plataforma","Buena estrategia","Obligatorio","Gratis"],"correcta":0}],"c-ia-turismo-m3":[{"p":"La promoción de un hospedaje funciona mejor cuando…","ops":["También promueve el destino","Solo habla de precios","Copia a la competencia","No publica nada"],"correcta":0},{"p":"Una imagen generada con IA de un espacio que no existe…","ops":["Genera reclamos y reseñas negativas","Es una buena práctica","Es obligatoria","No afecta"],"correcta":0},{"p":"Tarifa promedio =","ops":["Ingreso ÷ noches vendidas","Ingreso ÷ noches disponibles","Noches vendidas ÷ ingreso","Precio de lista"],"correcta":0},{"p":"Ingreso por noche disponible =","ops":["Ingreso ÷ noches disponibles","Ingreso ÷ noches vendidas","Ocupación × 100","Nada"],"correcta":0},{"p":"Antes de bajar la tarifa conviene…","ops":["Probar valor agregado, paquetes o mínimo de noches","Bajarla de inmediato","Cerrar","Subirla al doble"],"correcta":0},{"p":"La distancia «a 5 minutos de la playa»…","ops":["Se mide y se comprueba","Se estima a ojo","La da la IA","Se omite"],"correcta":0},{"p":"La reseña se pide…","ops":["Al final de la estancia con una liga directa","A cambio de un descuento","A cualquier desconocido","Nunca"],"correcta":0},{"p":"En turismo, la IA sirve sobre todo para…","ops":["Cotizar, responder, promover y organizar más rápido","Fijar tarifas sola","Confirmar disponibilidad","Sustituir al anfitrión"],"correcta":0}],"c-ia-turismo-m4":[{"p":"La fecha de liberación de un bloqueo indica…","ops":["Cuándo llega el grupo","Hasta cuándo se sostienen las habitaciones no confirmadas","El día de pago del hotel","La fecha de la boda"],"correcta":1},{"p":"Con 29 de 40 habitaciones confirmadas, el porcentaje es…","ops":["29%","40%","72.5%","80%"],"correcta":2},{"p":"Punto de equilibrio de un tour =","ops":["Costos fijos ÷ (precio − costo variable)","Precio × personas","Costos fijos × precio","Precio ÷ costo variable"],"correcta":0},{"p":"Si la IA dice que tu tour no requiere permisos…","ops":["Lo pones en la ficha","Le preguntas otra vez","Lo ignoras","Verificas el requisito vigente con la autoridad"],"correcta":3},{"p":"Para verificar una política traducida…","ops":["Retrotraducción y comparación frase por frase","Confías en la IA","Solo revisas la ortografía","La mandas sin revisar"],"correcta":0},{"p":"La foto del pasaporte de un huésped…","ops":["Se pega en la IA","Solo se maneja en tus sistemas autorizados","Se publica","Se reenvía al equipo"],"correcta":1}],"c-ia-turismo-m5":[{"p":"6 habitaciones × 2 noches × $3,200 =","ops":["$32,400","$19,200","$38,400","$6,400"],"correcta":2},{"p":"Si la traducción de tu política da más días de cancelación que el original…","ops":["Corriges la traducción para que diga lo mismo","La dejas, atrae clientes","Cambias tu política","La quitas"],"correcta":0},{"p":"Para promover tu hotel usas…","ops":["Imágenes generadas de espacios ideales","Fotos reales y distancias medidas","Fotos de hoteles vecinos","Solo texto sin revisar"],"correcta":1},{"p":"Responder una reseña con el número de habitación del huésped…","ops":["Da credibilidad","Es obligatorio","Es buena práctica","Expone datos del huésped: no se hace"],"correcta":3},{"p":"Tu lista de verificación del kit incluye revisar…","ops":["Tarifas, políticas, horarios, fotos y datos del huésped","Solo la ortografía","El color del logotipo","Nada"],"correcta":0},{"p":"En turismo, la responsabilidad de lo que prometes al huésped es…","ops":["De la IA","Tuya y de tu negocio","De la plataforma","Del huésped"],"correcta":1}]}});
